import Foundation

enum AppSizeClass {
    case compact
    case regular
}

struct SizeClassInspector {
    let horizontal: AppSizeClass

    var isCompactWidth: Bool {
        horizontal == .compact
    }
}

let inspector = SizeClassInspector(horizontal: .compact)
print("Compact: \(inspector.isCompactWidth)")

import Foundation

struct ViewFitEvaluator {
    static func pickBestFit(availableWidth: Double) -> String {
        let candidateAWidth = 500.0
        let candidateBWidth = 280.0

        if candidateAWidth <= availableWidth {
            return "FullWideRow"
        } else if candidateBWidth <= availableWidth {
            return "CompactRow"
        } else {
            return "MinimalIcon"
        }
    }
}

print("Fits: \(ViewFitEvaluator.pickBestFit(availableWidth: 300.0))")

