import Foundation

struct SplitViewRatio {
    static func fraction(appWidth: Double, totalWidth: Double) -> String {
        let ratio = appWidth / totalWidth
        if ratio < 0.4 { return "0.33" }
        if ratio < 0.6 { return "0.50" }
        return "0.66"
    }
}

